//! ↩️ reorder-images leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfImage;
use crate::artifacts::gltf::schema::mutations::reorder_images::mutation::{validate, GltfReorderImagesPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{images_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-images.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderImagesInverseOperation { Insert { position: usize, item: GltfImage }, Delete { index: usize, removed: GltfImage }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderImagesInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderImagesPayload, pub operation: GltfReorderImagesInverseOperation }
async fn operation(payload: &GltfReorderImagesPayload, base: &GltfSnapshot) -> GltfReorderImagesInverseOperation { GltfReorderImagesInverseOperation::Reorder { order: (0..payload.order.len()).map(|index| payload.order.iter().position(|value| *value == index).unwrap()).collect() } }
async fn touched_paths(payload: &GltfReorderImagesPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/images/{}", index)).chain(std::iter::empty()).collect() }
pub async fn validate_inverse(inverse: &GltfReorderImagesInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub async fn apply_inverse(inverse: &GltfReorderImagesInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfReorderImagesInverseOperation::Insert { position, .. } if *position > after.document.images.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/images", "position must be within the collection")), GltfReorderImagesInverseOperation::Delete { index, .. } if *index >= after.document.images.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/images", "index must address an item")), GltfReorderImagesInverseOperation::Move { index, position } if *index >= after.document.images.len() || *position >= after.document.images.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/images", "indices must address items")), GltfReorderImagesInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.images.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.images.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/images", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfReorderImagesInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Images, &Change::Insert(*position))?; next.document.images.insert(*position, item.clone());  }, GltfReorderImagesInverseOperation::Delete { index, .. } => { images_op(&mut next, GltfTopLevelFamily::Images, *index, None, None)?;  }, GltfReorderImagesInverseOperation::Move { index, position } => { images_op(&mut next, GltfTopLevelFamily::Images, *index, Some(*position), None)?;  }, GltfReorderImagesInverseOperation::Reorder { order } => { images_op(&mut next, GltfTopLevelFamily::Images, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(inverse: &GltfReorderImagesInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub async fn derive(payload: &GltfReorderImagesPayload, base: &GltfSnapshot) -> Result<GltfReorderImagesInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderImagesInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
